/* Topbar branding - Trường Cao đẳng Huế */
body .topbar .topbar-dashboard-brand {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    padding-left: 0.25rem;
}

body .topbar .topbar-brand-logo {
    width: 32px;
    height: 32px;
    object-fit: contain;
    flex-shrink: 0;
}

body .topbar .topbar-brand-text {
    display: flex;
    flex-direction: column;
    line-height: 1.25;
    min-width: 0;
}

body .topbar .topbar-brand-title {
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--sch-primary);
    white-space: nowrap;
}

body .topbar .topbar-brand-school {
    font-size: 0.78rem;
    font-weight: 500;
    color: #6c7a89;
    white-space: nowrap;
}

body .topbar .topbar-portal-btn {
    font-size: 0.82rem;
    font-weight: 600;
    border-color: rgba(13, 42, 107, 0.35);
    color: var(--sch-primary);
    white-space: nowrap;
}

body .topbar .topbar-portal-btn:hover,
body .topbar .topbar-portal-btn:focus {
    background-color: var(--sch-primary);
    border-color: var(--sch-primary);
    color: #fff;
}

@media (max-width: 767.98px) {
    body .topbar .topbar-brand-school {
        display: none;
    }

    body .topbar .topbar-brand-title {
        font-size: 0.88rem;
    }

    body .topbar .topbar-portal-btn-text {
        display: none;
    }

    body .topbar .topbar-portal-btn .bi {
        margin-right: 0 !important;
    }
}
